import { Univer } from '@univerjs/core';

const univer = new Univer();
univer.registerPlugin(UniverSheetsPlugin);

import { AGUIClient } from '@ag-ui/core';

const client = new AGUIClient({ endpoint: 'https://api.agent.local' });
client.on('message', (event) => console.log(event));

#include "ggml.h"

struct ggml_init_params params = { .mem_size = 16*1024*1024, .mem_buffer = NULL, .no_alloc = false };
struct ggml_context * ctx = ggml_init(params);

import { configureAgent } from 'modern-web-guidance';

configureAgent({
  targetStandards: 'modern-web-2026',
  strictLegacyCheck: true
});

import { Button } from '@astryxdesign/core';

export default function App() {
  return <Button variant="primary">Agent Ready</Button>;
}

import { OpenMausBot } from '@openmaus/core';

const bot = new OpenMausBot({
  model: 'claude-3-5-sonnet',
  environment: 'local-vm'
});

bot.startChat();

import { applyTasteSkill } from 'taste-skill';

const agent = applyTasteSkill({
  theme: 'modern-dark',
  references: ['./assets/design-ref.png']
});
agent.run();

import { ShotCraft, Preset } from 'video-shotcraft';

const video = new ShotCraft({
  recipe: Preset.CinematicProductPromo,
  beatSync: true
});
video.render('./output/promo.mp4');
